import{R as e,e as i,f as o,U as n}from"./chunks/framework.ywem4qy5.js";const p=JSON.parse('{"title":"LiveChat","description":"","frontmatter":{},"headers":[],"relativePath":"integrations/help-desk/livechat.md","filePath":"integrations/help-desk/livechat.md","lastUpdated":1775908585000}'),a={name:"integrations/help-desk/livechat.md"};function r(l,t,s,h,g,c){return i(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="livechat" tabindex="-1">LiveChat <a class="header-anchor" href="#livechat" aria-label="Permalink to &quot;LiveChat&quot;">​</a></h1><p>Follow the below steps to connect to the LiveChat API.</p><h3 id="step-1-create-the-integration" tabindex="-1">Step 1. Create the Integration <a class="header-anchor" href="#step-1-create-the-integration" aria-label="Permalink to &quot;Step 1. Create the Integration&quot;">​</a></h3><ol><li>Navigate to <strong>Formie</strong> → <strong>Settings</strong> → <strong>Help Desk</strong>.</li><li>Click the <strong>New Integration</strong> button.</li><li>Select <strong>LiveChat</strong> as the <strong>Integration Provider</strong>.</li></ol><h3 id="step-2-connect-to-the-livechat-api" tabindex="-1">Step 2. Connect to the LiveChat API <a class="header-anchor" href="#step-2-connect-to-the-livechat-api" aria-label="Permalink to &quot;Step 2. Connect to the LiveChat API&quot;">​</a></h3><ol><li>Go to <a href="https://developers.livechat.com/console/" target="_blank">LiveChat Developer Console</a> and log in.</li><li>Navigate to <strong>Apps</strong>.</li><li>Click the <strong>Build App</strong> button, and fill out the app name and description.</li><li>Proceed to <strong>Configure a widget</strong> using the default settings.</li><li>Proceed to <strong>Configure Authorization</strong>.</li><li>In the <strong>Redirect URI whitelist</strong> field, enter the value from the <strong>Redirect URI</strong> field in Formie.</li><li>Copy the <strong>Client ID</strong> from LiveChat and paste in the <strong>Client ID</strong> field in Formie.</li><li>Copy the <strong>Client Secret</strong> from LiveChat and paste in the <strong>Client Secret</strong> field in Formie.</li><li>Set the required scopes (such as <code>tickets.write</code> and <code>tickets.read</code>).</li><li>Go to <a href="https://my.livechatinc.com" target="_blank">LiveChat</a>.</li><li>Navigate to <strong>Settings</strong> → <strong>Chat Page</strong>.</li><li>Copy <em>just</em> the number in the URL from LiveChat and paste in the <strong>License ID</strong> field in Formie.</li></ol><h3 id="step-3-test-connection" tabindex="-1">Step 3. Test Connection <a class="header-anchor" href="#step-3-test-connection" aria-label="Permalink to &quot;Step 3. Test Connection&quot;">​</a></h3><ol><li>Save this integration.</li><li>Click on the <strong>Connect</strong> button in the right-hand sidebar.</li></ol><h3 id="step-4-form-settings" tabindex="-1">Step 4. Form Settings <a class="header-anchor" href="#step-4-form-settings" aria-label="Permalink to &quot;Step 4. Form Settings&quot;">​</a></h3><ol><li>Go to the form you want to enable this integration on.</li><li>Click the <strong>Integrations</strong> tab.</li><li>In the left-hand sidebar, select the name you gave the integration.</li><li>Enable the integration and fill out all required fields.</li><li>Click <strong>Save</strong> to save the form.</li></ol>',10)])])}const m=e(a,[["render",r]]);export{p as __pageData,m as default};
